@app.route("/api/answer", methods=["POST"])
def record_answer():
    d=request.get_json() or {}; n=norm(d.get("name")); q=d.get("question","")
    if not n or not q: return jsonify({"ok":False}),400
    if n not in USERS: USERS[n]={"display_name":d.get("name"),"password":"","wins":0,"losses":0,"last_seen":time.time(),"friends":[],"requests":[],"stage":0,"logged_out":False,"history":{}}
    if "history" not in USERS[n]: USERS[n]["history"]={}
    h=USERS[n]["history"].get(q,{"asked":0,"correct":0,"wrong":0,"last":0,"cat":"","mode":""})
    h["asked"]=h.get("asked",0)+1
    if d.get("correct"): h["correct"]=h.get("correct",0)+1
    else: h["wrong"]=h.get("wrong",0)+1
    h["last"]=time.time()
    if d.get("cat"): h["cat"]=d.get("cat")
    if d.get("mode"): h["mode"]=d.get("mode")
    USERS[n]["history"][q]=h; USERS[n]["last_seen"]=time.time(); save_users()
    return jsonify({"ok":True,"asked":h["asked"]})
@app.route("/api/logout", methods=["POST"])
def logout():
    d=request.get_json(silent=True) or {}
    if not d:
        try: d=request.get_json(force=True,silent=True) or {}
        except: d={}
    n=norm(d.get("name"))
    if n in USERS:
        USERS[n]["logged_out"]=True
        save_users()
    return jsonify({"ok":True})
@app.route("/api/online", methods=["POST"])
def online():
    d=request.get_json() or {}; n=norm(d.get("name"))
